from functools import lru_cache

def count_ways(n, k):
    MOD = 10**9 + 7

    @lru_cache(None)
    def dp(i, j, rmin, cmin):
        if i == n:
            return 1 if rmin == 1 else 0
        if j == n:
            return dp(i+1, 0, rmin, cmin)
        result = 0
        for x in range(1, min(k, max(rmin, cmin)) + 1):
            result += dp(i, j+1, max(rmin, x), max(cmin, x))
            result %= MOD
        return result

    return dp(0, 0, 1, 1)

