        return k % MOD

    dp = [[0] * (n+1) for _ in range(k+1)]
    for i in range(1, k+1):
        dp[i][1] = 1

    for i in range(1, k+1):
        for j in range(2, n+1):
            dp[i][j] = sum(dp[x][j-1] for x in range(1, i+1)) % MOD

    result = 0
    for i in range(1, k+1):
        result += dp[i][n]

    return result % MOD

